function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };

  const O='#5a3a10', Bag='#c45c14', BagLt='#e07830', BagDk='#8a3c0c', Gold='#f4c020';
  // money bag
  px(18,20,28,34,O); px(19,21,26,32,Bag);
  px(19,21,26,3,BagLt); px(19,50,26,3,BagDk);
  // neck
  px(26,12,12,12,O); px(27,13,10,10,BagLt);
  // $ 
  px(28,30,8,2,Gold); px(30,28,4,16,Gold); px(28,34,8,2,Gold); px(28,42,8,2,Gold);

}
